// Vendored benchmark fixture "dependency" (scripts/bench/fixtures/node_modules/bench-dep).
// Lives under a committed node_modules/ dir so capwall's attribution walks a real
// `node_modules/bench-dep/…` path and resolves the owning package name, instead of
// short-circuiting to the `<app>` sentinel — see scripts/bench/README.md for why that
// matters for the measurement. Mirrors packages/core/test/fixtures/node_modules/fixture-dep.
//
// Captures whatever `fs`/`net` it resolves at require() time: the real Node builtin when
// required BEFORE capwall installs (the benchmark's baseline instance), capwall's shim when
// required fresh AFTER install (the benchmark's shimmed instance). bench.mjs exploits this to
// run both side by side in the same process.
"use strict";
const fs = require("fs");
const path = require("path");

const DATA = path.join(__dirname, "data.txt");

/** Plain sync read — the hot-path operation the fs scenario times. */
exports.readSync = () => fs.readFileSync(DATA, "utf8");

/**
 * Invoke `attributeCallerFn` from a frame that lives under node_modules/bench-dep, so the
 * stack-walk resolves a real package name (not `<app>`). Used to time attribution alone,
 * decoupled from a full shimmed fs call.
 */
exports.callAttribute = (attributeCallerFn, opts) => attributeCallerFn(opts);

/**
 * Attempt a net connect that the benchmark's policy never grants to "bench-dep". In enforce
 * mode the net shim throws CapabilityError synchronously, before any socket opens (see
 * packages/core/test/net.test.ts) — so this is a fast, deterministic way to time the
 * attribute→evaluate→throw path with no real I/O.
 */
exports.connectDenied = (host, port) => {
  const net = require("net");
  try {
    const s = net.connect({ host, port });
    s.on("error", () => {});
    s.destroy();
    return { threw: false };
  } catch (err) {
    return { threw: true, name: err && err.name };
  }
};
